// src/components/ViewSendMessages.jsx
import React, { useEffect, useState, useRef } from "react";
import "./CSS/ViewSendMessages.css";

const ViewSendMessages = ({ selectedUser, currentUser, onBack }) => {
  const scrollRef = useRef(null);
  const [messages, setMessages] = useState([]);
  const [newMessage, setNewMessage] = useState("");
  const [file, setFile] = useState(null);

  useEffect(() => {
    if (!selectedUser || !currentUser) return;

    fetch("http://localhost:5000/get-conversation", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        user1: currentUser.email,
        user2: selectedUser.email,
      }),
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          setMessages(data.messages);
        } else {
          alert("Failed to load conversation");
        }
      })
      .catch(() => alert("Error loading messages"));
  }, [selectedUser, currentUser]);

  const handleSend = async () => {
    if (!newMessage.trim() && !file) return;

    let payload = {
      sender: currentUser.email,
      receiver: selectedUser.email,
    };

    if (file) {
      const reader = new FileReader();
      reader.onload = async () => {
        payload.message = reader.result;
        payload.filename = file.name;
        await sendPayload(payload);
        setFile(null);
      };
      reader.readAsDataURL(file);
    } else {
      payload.message = newMessage.trim();
      await sendPayload(payload);
    }

    setNewMessage("");
  };

  const sendPayload = async (payload) => {
    fetch("http://localhost:5000/send-message", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })
      .then((res) => res.json())
      .then((data) => {
        if (data.success) {
          setMessages((prev) => [
            ...prev,
            {
              sender: currentUser.email,
              receiver: selectedUser.email,
              message: payload.filename ? `📎 ${payload.filename}` : payload.message,
              date: new Date().toISOString().split("T")[0],
              time: new Date().toLocaleTimeString(),
            },
          ]);
          scrollToBottom();
        } else {
          alert("Failed to send message");
        }
      })
      .catch(() => alert("Network error sending message"));
  };

  const scrollToBottom = () => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  };

  useEffect(scrollToBottom, [messages]);

  return (
    <div className="chat-container">
      <div className="chat-header">
        <button className="back-btn" onClick={onBack}>←</button>
        <div className="chat-user">
          <p>{selectedUser.name}</p>
          <p>{selectedUser.email}</p>
        </div>
      </div>

      <div className="chat-body" ref={scrollRef}>
        {messages.map((msg, idx) => (
          <div
            key={idx}
            className={`chat-bubble ${msg.sender === currentUser.email ? "sent" : "received"}`}
          >
            <p>{msg.message}</p>
            <span className="chat-time">{msg.date} {msg.time}</span>
          </div>
        ))}
      </div>

      <div className="chat-input-area">
        <label className="file-btn">
          +File
          <input
            type="file"
            onChange={(e) => setFile(e.target.files[0])}
            style={{ display: "none" }}
          />
        </label>
        <input
          type="text"
          placeholder="message"
          value={newMessage}
          onChange={(e) => setNewMessage(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && handleSend()}
        />
        <button className="send-btn" onClick={handleSend}>▶</button>
      </div>
    </div>
  );
};

export default ViewSendMessages;
